Q: Sequelize.js: Include unexpected. Element has to be either a Model, an Association or an object A: <p>You are correct when you say:</p>
<blockquote>
<p>I suspect it has to do with the fact that AccountCategory is placed after Account in my models folder when the models are being set up and thus not processed (associated).</p>
</blockquote>
<p><strong>TLDR:</strong> Add a new function to your model class definition similar to the <code>associate</code> function, and use the <a href="https://sequelize.org/api/v6/class/src/model.js%7Emodel#static-method-addScope" rel="nofollow noreferrer">addScope</a> function to define any scopes that reference other models that may have not been initialized due to file tree order. Finally, call that new function the same way you call <code>db[modelName].associate</code> in your <code>models.index.js</code> file.</p>
<p>I had a similar problem and solved it by defining any scopes that reference any models, e.g. in an <code>include</code>, after all the models are initialized after running the following in your <code>models/index.js</code> file.</p>
<p>Here is an example:</p>
<p><strong>models/agent.js</strong></p>
<pre><code>'use strict';
const { Model } = require('sequelize');
const camelCase = require('lodash/camelCase');
const { permissionNames } = require('../../api/constants/permissions');

module.exports = (sequelize, DataTypes) =&gt; {
  /**
   * @summary Agent model
   */
  class Agent extends Model {}

  Agent.init(
    {
      id: {
        type: DataTypes.INTEGER,
        allowNull: false,
        autoIncrement: true,
        primaryKey: true,
      },
      firstName: {
        type: DataTypes.STRING,
        allowNull: false,
      },
      lastName: {
        type: DataTypes.STRING,
        allowNull: false,
      },
    },
    {
      sequelize,
      scopes: {
        // Works because the agent-role.js file / model comes before agent.js in the file tree
        [camelCase(permissionNames.readAgentRoles)]: {
          include: [
            {
              model: sequelize.models.AgentRole,
            },
          ],
        },
        // Doesn't work due to import order in models/index.js, i.e., agent.js is before role.js in the file tree
        // [camelCase(permissionNames.readRoles)]: {
        //   include: [
        //     {
        //       model: sequelize.models.Role,
        //     },
        //   ],
        // },
      },
    }
  );

  Agent.associate = function (models) {
    Agent.belongsToMany(models.Role, {
      through: 'AgentRole',
      onDelete: 'CASCADE', // default for belongsToMany
      onUpdate: 'CASCADE', // default for belongsToMany
      foreignKey: {
        name: 'agentId',
        type: DataTypes.INTEGER,
        allowNull: false,
      },
    });
    Agent.hasMany(models.AgentRole, {
      onDelete: 'CASCADE',
      onUpdate: 'CASCADE',
      foreignKey: {
        name: 'agentId',
        type: DataTypes.INTEGER,
        allowNull: false,
      },
    });
  };

  // Add a custom `addScopes` function to call after initializing all models in `index.js`
  Agent.addScopes = function (models) {
    Agent.addScope(camelCase(permissionNames.readRoles), {
      include: [
        {
          model: models.Role,
        },
      ],
    });
  };

  return Agent;
};
</code></pre>
<p><strong>models/index.js</strong></p>
<pre><code>'use strict';

const fs = require('fs');
const path = require('path');
const Sequelize = require('sequelize');
const basename = path.basename(__filename);
const config = require('../database-config.js');
const db = {};

const sequelize = new Sequelize(config.database, config.username, config.password, config);

/**
 * Import and attach all of the model definitions within this 'models' directory to the sequelize instance.
 */
fs.readdirSync(__dirname)
  .filter((file) =&gt; {
    return file.indexOf('.') !== 0 &amp;&amp; file !== basename &amp;&amp; file.slice(-3) === '.js';
  })
  .forEach((file) =&gt; {
    // Here is where file tree order matters... the sequelize const may not have the required model added to it yet
    const model = require(path.join(__dirname, file))(sequelize, Sequelize.DataTypes);
    db[model.name] = model;
  });

Object.keys(db).forEach((modelName) =&gt; {
  if (db[modelName].associate) {
    db[modelName].associate(db);
  }
  // We need to add scopes that reference other tables once they have all been initialized
  if (db[modelName].addScopes) {
    db[modelName].addScopes(db);
  }
});

db.sequelize = sequelize;
db.Sequelize = Sequelize;

module.exports = db;
</code></pre>
<p>Goodluck!</p>

Q: Angular 2 - How to upload file and store in local folder A: <p>You could do it this way:</p>

<pre><code>//in html
&lt;input type="file" (click)="handleFileInput($event.target.value)"&gt;

//in .ts file
handleFileInput(file: FileList) {
    this.fileToUpload = file.item(0);
}
</code></pre>

<p>you can append <code>this.fileToUpload</code> to <code>formdata</code>.</p>

Q: Unity NGO NetworkList of struct that contains an array of struct A: <p><code>SimpleDataStruct[]</code> is the part that prevents <code>ContainerStruct</code> from being used with <code>NetworkList&lt;T&gt;</code>. An array is a managed/reference type, even though <code>SimpleDataStruct</code> itself is a value type.</p>
<p><code>NetworkList&lt;T&gt;</code> requires <code>T</code> to be an unmanaged type, so this won't work:</p>
<pre><code>public struct ContainerStruct : INetworkSerializable
{
    public ulong ownerID;
    public SimpleDataStruct[] array; // managed reference
    public int moreData;
}
</code></pre>
<p>You generally have two options.</p>
<p><strong>1. Flatten the data</strong></p>
<p>Instead of having a list of containers where each container owns another array, keep the network data in separate collections and use an ID/index to associate the unit data with its container.</p>
<p>For example:</p>
<pre><code>public struct ContainerStruct : INetworkSerializable
{
    public ulong ownerID;
    public int firstUnitIndex;
    public int unitCount;
    public int moreData;

    public void NetworkSerialize&lt;T&gt;(BufferSerializer&lt;T&gt; serializer)
        where T : IReaderWriter
    {
        serializer.SerializeValue(ref ownerID);
        serializer.SerializeValue(ref firstUnitIndex);
        serializer.SerializeValue(ref unitCount);
        serializer.SerializeValue(ref moreData);
    }
}
</code></pre>
<p>And then keep the <code>SimpleDataStruct</code> values in a separate <code>NetworkList&lt;SimpleDataStruct&gt;</code>.</p>
<pre><code>private NetworkList&lt;ContainerStruct&gt; containers;
private NetworkList&lt;SimpleDataStruct&gt; units;
</code></pre>
<p>The container can then refer to its range of units using <code>firstUnitIndex</code> and <code>unitCount</code>.</p>
<p><strong>2. Use a fixed-size unmanaged container</strong></p>
<p>If the maximum number of <code>SimpleDataStruct</code> entries per container is known, you can replace the managed array with a fixed-size unmanaged representation. The important part is that the resulting struct must still satisfy NGO's unmanaged requirements.</p>
<p>For example, don't use:</p>
<pre><code>SimpleDataStruct[] array;
</code></pre>
<p>as a field of a <code>NetworkList</code> element.</p>
<p>For an army system where the number of units can vary, I would generally prefer the <strong>first approach</strong>. A network list of armies plus a separate network list of unit records is easier to synchronize and avoids putting a variable-length managed collection inside a network struct.</p>
<p>Also, you don't need to make every nested object a value type simply because it is serializable. The important distinction here is that <strong><code>INetworkSerializable</code> controls serialization, while <code>NetworkList&lt;T&gt;</code> has additional type constraints on <code>T</code></strong>.</p>
<p>So the immediate problem isn't <code>INetworkSerializable</code>; it's the managed <code>SimpleDataStruct[]</code> field inside the <code>NetworkList</code> element.</p>
